          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          requiredMessage: "Error: Enter your email address.",
          formatMessage: "Error: Enter a valid email address, like name@example.com."
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helpText: "Use 10 to 15 digits. You may include spaces, dashes, parentheses, or a leading plus sign.",
          formatMessage: "Error: Enter a phone number with 10 to 15 digits, or leave this field blank."
        }
      ];

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const allowedPhonePattern = /^\+?[0-9\s().-]+$/;

