+          <h1 id="page-title">Contact support</h1>
+          <p class="intro">Tell us how to reach you and our support team will follow up with the next steps.</p>
+        </div>
+        <div id="contact-form-root"></div>
+      </section>
+    </main>
+
+    <script>
+      const fields = [
+        {
+          id: "full-name",
+          name: "fullName",
+          label: "Full name",
+          type: "text",
+          autocomplete: "name",
+          required: true,
+          requiredMessage: "Error: Enter your full name."
+        },
+        {
+          id: "email-address",
+          name: "email",
+          label: "Email address",
+          type: "email",
+          autocomplete: "email",
+          required: true,
+          requiredMessage: "Error: Enter your email address.",
+          formatMessage: "Error: Enter a valid email address, like name@example.com."
+        },
+        {
+          id: "phone-number",
+          name: "phone",
+          label: "Phone number",
+          type: "tel",
+          autocomplete: "tel",
+          required: false,
+          helpText: "Use 10 to 15 digits. You may include spaces, dashes, parentheses, or a leading plus sign.",
+          formatMessage: "Error: Enter a phone number with 10 to 15 digits, or leave this field blank."
+        }
+      ];
+
+      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+      const allowedPhonePattern = /^\+?[0-9\s().-]+$/;
+
+      function FormField({ id, name, label, type, autocomplete, required, helpText }) {
+        const helpId = `${id}-help`;
+        const errorId = `${id}-error`;
+        const describedBy = [helpText ? helpId : null, errorId].filter(Boolean).join(" ");
+        const requiredText = required
+          ? '<span class="required-marker" aria-hidden="true">*</span>'
+          : '<span class="optional-text">(optional)</span>';
