+        return `
+          <div class="form-field">
+            <label for="${id}">${label} ${requiredText}</label>
+            <input
+              id="${id}"
+              name="${name}"
+              type="${type}"
+              autocomplete="${autocomplete}"
+              ${required ? "required" : ""}
+              aria-describedby="${describedBy}"
+              aria-invalid="false"
+            >
+            ${helpText ? `<p class="helper-text" id="${helpId}">${helpText}</p>` : ""}
+            <p class="validation-message" id="${errorId}" hidden></p>
+          </div>
+        `;
+      }
+
+      function ContactForm({ fields }) {
+        return `
+          <form id="support-contact-form" novalidate>
+            <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
+            ${fields.map((field) => FormField(field)).join("")}
+            <button class="submit-button" type="submit">Send support request</button>
+            <p class="status-message" id="form-status" aria-live="polite"></p>
+          </form>
+        `;
+      }
+
+      function getFieldError(field, value) {
+        const trimmedValue = value.trim();
+
+        if (field.required && !trimmedValue) {
+          return field.requiredMessage;
+        }
+
+        if (field.name === "email" && trimmedValue && !emailPattern.test(trimmedValue)) {
+          return field.formatMessage;
+        }
+
+        if (field.name === "phone" && trimmedValue) {
+          const digitCount = trimmedValue.replace(/\D/g, "").length;
+
+          if (!allowedPhonePattern.test(trimmedValue) || digitCount < 10 || digitCount > 15) {
+            return field.formatMessage;
+          }
+        }
