+      function validateField(field) {
+        const input = document.getElementById(field.id);
+        const message = getFieldError(field, input.value);
+        setFieldError(input, message);
+        return !message;
+      }
+
+      function initializeContactForm() {
+        const root = document.getElementById("contact-form-root");
+        root.innerHTML = ContactForm({ fields });
+
+        const form = document.getElementById("support-contact-form");
+        const status = document.getElementById("form-status");
+        let hasSubmitted = false;
+
+        fields.forEach((field) => {
+          const input = document.getElementById(field.id);
+
+          input.addEventListener("blur", () => {
+            validateField(field);
+          });
+
+          input.addEventListener("input", () => {
+            if (hasSubmitted || input.getAttribute("aria-invalid") === "true") {
+              validateField(field);
+            }
+            status.textContent = "";
+          });
+        });
