+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          hasSubmitted = true;
+
+          const invalidField = fields.find((field) => !validateField(field));
+
+          if (invalidField) {
+            document.getElementById(invalidField.id).focus();
+            status.textContent = "";
+            return;
+          }
+
+          form.reset();
+          fields.forEach((field) => {
+            setFieldError(document.getElementById(field.id), "");
+          });
+          status.textContent = "Your support request is ready to send.";
+          hasSubmitted = false;
+        });
+      }
+
+      initializeContactForm();
+    </script>
+  </body>
+</html>
+

')

