      .intro {
        margin: 1rem 0 0;
        color: #cbd5e1;
        font-size: 1.0625rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
        padding: 1rem clamp(1.25rem, 5vw, 2.5rem) clamp(1.5rem, 5vw, 2.5rem);
      }

      .required-note {
        margin: 0;
        color: #cbd5e1;
        font-size: 0.95rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        color: #f8fafc;
        font-weight: 700;
      }

      .required-marker {
        color: #fca5a5;
      }

      input {
        width: 100%;
        border: 1px solid #475569;
        border-radius: 0.9rem;
        background: rgba(2, 6, 23, 0.76);
        color: #f8fafc;
        font: inherit;
