  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="support-card" aria-labelledby="page-title">
        <div class="card-header">
          <h1 id="page-title">Contact support</h1>
          <p class="intro">Tell us how to reach you and our support team will follow up with the next steps.</p>
        </div>
        <form id="support-contact-form" novalidate>
          <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

          <div class="form-field">
            <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
              aria-invalid="false"
            >
            <p class="validation-message" id="full-name-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required-marker" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-address-error"
              aria-invalid="false"
            >
            <p class="validation-message" id="email-address-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number <span class="optional-text">(optional)</span></label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              autocomplete="tel"
              aria-describedby="phone-number-help phone-number-error"
              aria-invalid="false"
            >
            <p class="helper-text" id="phone-number-help">Use 10 to 15 digits. You may include spaces, dashes, parentheses, or a leading plus sign.</p>
            <p class="validation-message" id="phone-number-error" hidden></p>
          </div>

          <button class="submit-button" type="submit">Send support request</button>
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          requiredMessage: "Error: Enter your full name."
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          requiredMessage: "Error: Enter your email address.",
          formatMessage: "Error: Enter a valid email address, like name@example.com."
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helpText: "Use 10 to 15 digits. You may include spaces, dashes, parentheses, or a leading plus sign.",
          formatMessage: "Error: Enter a phone number with 10 to 15 digits, or leave this field blank."
        }
      ];

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const allowedPhonePattern = /^\+?[0-9\s().-]+$/;

      function FormField({ id }) {
        return {
          input: document.getElementById(id),
          errorElement: document.getElementById(`${id}-error`)
        };
      }

      function ContactForm() {
        return {
          form: document.getElementById("support-contact-form"),
          status: document.getElementById("form-status"),
          fields: fields.map((field) => ({
            ...field,
            elements: FormField(field)
          }))
        };
      }

      function getFieldError(field, value) {
        const trimmedValue = value.trim();

        if (field.required && !trimmedValue) {
          return field.requiredMessage;
        }

        if (field.name === "email" && trimmedValue && !emailPattern.test(trimmedValue)) {
          return field.formatMessage;
        }

        if (field.name === "phone" && trimmedValue) {
          const digitCount = trimmedValue.replace(/\D/g, "").length;

          if (!allowedPhonePattern.test(trimmedValue) || digitCount < 10 || digitCount > 15) {
            return field.formatMessage;
          }
        }

        return "";
      }

      function setFieldError({ input, errorElement }, message) {
        input.setAttribute("aria-invalid", message ? "true" : "false");
        errorElement.textContent = message;
        errorElement.hidden = !message;
      }

      function validateField(field) {
        const message = getFieldError(field, field.elements.input.value);
        setFieldError(field.elements, message);
        return !message;
      }

      function initializeContactForm() {
        const { form, status, fields: contactFields } = ContactForm();
        let hasSubmitted = false;

        contactFields.forEach((field) => {
          const { input } = field.elements;

          input.addEventListener("blur", () => {
            validateField(field);
          });

          input.addEventListener("input", () => {
            if (hasSubmitted || input.getAttribute("aria-invalid") === "true") {
              validateField(field);
            }
            status.textContent = "";
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          hasSubmitted = true;

          const invalidField = contactFields.find((field) => !validateField(field));

          if (invalidField) {
            invalidField.elements.input.focus();
            status.textContent = "";
            return;
          }

          form.reset();
          contactFields.forEach((field) => {
            setFieldError(field.elements, "");
          });
          status.textContent = "Your support request is ready to send.";
          hasSubmitted = false;
        });
      }

      initializeContactForm();
    </script>
  </body>
</html>
